MUTACOES = [('c_k0_b', '                if v > 0x4b { 1 } else if v >= 0x28 { 2 } else if v >= 10 { 3 } else { low(-30) }', '                if v > 0x4b { 1 } else if v >= 0x28 { 3 } else if v >= 10 { 3 } else { low(-30) }'), ('c_tipo5_b', '    if c.contract_type() & 0x3f == 5 {\n        return 8;', '    if c.contract_type() & 0x3f == 5 {\n        return 7;'), ('o_campos', '    for o in [0x36, 0x38, 0x34] {', '    for o in [0x36, 0x34, 0x38] {'), ('r_banco', '            cod2[i] = w(curtos, j);', '            cod2[i] = w(codes, j);'), ('r_idade', '            3 => !p.is_null() && read_i8(rule + 1) < (p.age() as i8),', '            3 => !p.is_null() && read_i8(rule + 1) <= (p.age() as i8),'), ('n_veterano', '            Some(0x9689e0)', '            Some(0x968968)'), ('t_item', '        if *p == read_i32(e) {', '        if *p == read_i32(e + 4) {'), ('m_marca', '    (t.promoted_count() != 0 && (t.league_flags() as u8) & 2 != 0) as u32', '    (t.promoted_count() != 0 && (t.league_flags() as u8) & 1 != 0) as u32'), ('f_estado', '        2 | 3 | 4 | 0x10 | 0x14 => 1,', '        2 | 3 | 0x10 | 0x14 => 1,'), ('f_fase', '        0xf => (o.response_round() >= 3) as u32,', '        0xf => (o.response_round() >= 2) as u32,'), ('m_alguma', '    any_news_for_player(average, *id, |_| true) as u8', '    any_news_for_player(average, *id, |r| *((r + 0x10) as *const u8) != 0) as u8'), ('d_sem_regra', '    if k == -1 {\n        return;\n    }\n    let rules', '    if k <= 0 {\n        return;\n    }\n    let rules'), ('d_43', '    for k in 0..43usize {', '    for k in 0..42usize {'), ('t_desmarca', '    *staff_flags_ptr(TransferManagerFields(manager), id) &= 0xbf;', '    *staff_flags_ptr(TransferManagerFields(manager), id) &= 0x3f;'), ('t_vaga', '    if k < (table.offer_capacity() as i32) {', '    if k <= (table.offer_capacity() as i32) {'), ('r_ids', '    for o in [0x86, 0xc2, 0xc6, 0x4a, 0x5e, 0x72] {', '    for o in [0x86, 0xc2, 0xc6, 0x4a, 0x5e] {'), ('s_empate', '        if best == 0 || injury_word_0c(c) > injury_word_0c(Staff(best)) {', '        if best == 0 || injury_word_0c(c) >= injury_word_0c(Staff(best)) {'), ('c_clube', '    *club = (read_usize(G_CLUB_TABLE) as isize + (contract.club() as i32) as isize * (club::SIZE as isize)) as usize;', '    *club = (read_usize(G_CLUB_TABLE) as isize + (contract.club() as i32) as isize * 580) as usize;'), ('p_vaga', '        if read_i32(p) == id && *((p + held_ban::SLOT) as *const i8) == slot {', '        if read_i32(p) == id {'), ('a_torneio', '        if core::ptr::read_unaligned((p - 0x65) as *const usize) != 0 && object != 0 {', '        if core::ptr::read_unaligned((p - 0x65) as *const usize) != 0 && object != 0 && i > 0 {'), ('l_venda', '    remove_from_payment_list(TransferManagerFields(manager), id, 8, 0x880, 0x888, 9);', '    remove_from_payment_list(TransferManagerFields(manager), id, 8, 0x880, 0x888, 5);'), ('l_jogo', '    remove_from_payment_list(TransferManagerFields(manager), id, 2, 0x88c, 0x894, 0);', '    remove_from_payment_list(TransferManagerFields(manager), id, 1, 0x88c, 0x894, 0);'), ('l_conta', '    *((manager.addr() + how_many) as *mut i32) -= 1;', '    *((manager.addr() + how_many) as *mut i32) -= (j > i + 1) as i32;'), ('r_marca', '    for o in [0, 4, 8] {\n        write_i32(last + o, -1);', '    for o in [0, 4] {\n        write_i32(last + o, -1);'), ('c_saldo', '            1 => ((a.goals_for() as i32) - (a.goals_against() as i32), (b.goals_for() as i32) - (b.goals_against() as i32)),', '            1 => ((a.goals_for() as i32), (b.goals_for() as i32)),'), ('c_empate', '        add(h2h_entry::POINTS, (league.draw_points() as i8) as i16);', '        add(h2h_entry::POINTS, (league.draw_points() as i8) as i16 + 1);'), ('e_data', '    (clubs && w(8) == data_a && w(match_stats_entry::YEAR) == data_b) as i32', '    (clubs && w(8) == data_a) as i32'), ('b_tipo', '        return (game.category() == match_category::FRIENDLY) as u8 + 2;', '        return (game.category() == 1) as u8 + 1;')]
